INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.parent.no_interference', 'scene.school_fears.brave_society', 'dialogue', 'dialogue', NULL, NULL, NULL, NULL, 'parent', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'chairman_choice=no_interference', NULL, NULL, 'Разберутся. Только нашему ребёнку пока места нет ни в обществе, ни в разговоре.', '«Чёрное облако», сцена «Общество бесстрашных»; строка авторского источника 333.', 'Устав показывает, как страх превратился в исключение ребёнка.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 140);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.parent.observation', 'scene.school_fears.brave_society', 'dialogue', 'dialogue', NULL, NULL, NULL, NULL, 'parent', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'chairman_choice=observation', NULL, NULL, 'Тогда доказывать будут тетради, а не друг другу. Это они умеют дольше.', '«Чёрное облако», сцена «Общество бесстрашных»; строка авторского источника 330.', 'Устав показывает, как страх превратился в исключение ребёнка.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 80);
