INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.bad_joke', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', NULL, NULL, NULL, NULL, 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=bad_joke', NULL, NULL, 'Сказала взрослому: стая выберет, где шумнее всего. Думала, взрослый услышит шутку. Дети услышали правило. Здесь половина слов моя.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 229.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.borrowed_name', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', NULL, NULL, NULL, NULL, 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=borrowed_name', NULL, NULL, 'Моё имя там есть, моих слов нет. Вот кто рассказывает про облако: {addressee}. Спросите, откуда взялось предупреждение.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 227.', 'Колдунья называет закреплённого школьника, известного ей пересказом; его признание ещё не получено.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 2, NULL, 0, 30);
