INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.option.teacher_observes', 'scene.school_fears.witch_account', 'dialogue', 'choice', NULL, NULL, NULL, NULL, 'chairman', NULL, 'Председатель и собеседник расследуют школьный слух.', 'main', NULL, 'neutral', 'school_fears.secret=retelling|bad_joke', NULL, NULL, 'В школе проведут наблюдение без вас.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 260.', 'Колдунья раскрывает или уточняет источник слуха.', 'Сохранить ясный человеческий выбор без оценки его как правильного.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 2, NULL, 0, 80);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.retelling_no_tower', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', NULL, NULL, NULL, NULL, 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=retelling; church_absent', NULL, NULL, 'Я сказала соседке: к вечеру птица соберётся у старых деревьев. Кладбище добавила она, вашу крышу — школьник. Хорошая история: всё село строило.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 226.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('dialogue.school_fears.witch.retelling_tower', 'scene.school_fears.witch_account', 'dialogue', 'dialogue', NULL, NULL, NULL, NULL, 'witch', NULL, 'Председатель и собеседник расследуют школьный слух.', NULL, NULL, 'neutral', 'school_fears.secret=retelling; church_exists', NULL, NULL, 'Я сказала соседке: к вечеру птица соберётся у старых деревьев. Кладбище добавила она, колокольню — чей-то отец, вашу крышу — школьник. Хорошая история: всё село строило.', '«Чёрное облако», сцена «Что сказала колдунья»; строка авторского источника 225.', 'Колдунья раскрывает или уточняет источник слуха.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 10);
