INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.first_meeting.coat.question.worker', 'scene.elder.first_meeting', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'chairman', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, 'coat_question_by_avatar', 'neutral', 'Выбран avatar.key=worker; тема о сюртуке в первой встрече.', NULL, NULL, 'На вас у церкви сюртук был — не рабочая вещь. Откуда он?', 'Фактическое место работы Рябинина; одежда и инструмент берутся из партии.', 'Председатель помнит Рябинина в графском сюртуке у церкви, но сейчас спрашивает о происхождении вещи, а не оценивает человека.', 'Открыть короткую историю усадьбы голосом выбранного аватара.', 'Вежливая дистанция и характер аватара; деревенский уже знает об усадьбе. Не делать сюртук шуткой.', 'manual/characters/former-elder.md', 1, NULL, 0, 42);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.first_meeting.coat.reply.coat_worn', 'scene.elder.first_meeting', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, 'coat_reply_by_outfit', 'neutral', 'На Рябинине в этот момент графский сюртук.', NULL, NULL, 'Этот? В революцию усадьбу разбирали всем селом. Я вынес сюртук из пустого дома. У иных в селе и теперь графские вещи в сундуках лежат.', 'Фактическое место работы Рябинина; одежда и инструмент берутся из партии.', 'Сюртук взят из опустевшей усадьбы четырнадцать лет назад; часть прежней одежды хранится у других семей.', 'Без гордости и стыда сообщить факт села, не насмехаясь над нарядом.', '«Этот» относится к сюртуку, который сейчас на Рябинине. Не показывать грабёж и не придумывать судьбу графской семьи.', 'manual/characters/former-elder.md', 1, NULL, 0, 43);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.first_meeting.coat.reply.work_clothes', 'scene.elder.first_meeting', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, 'coat_reply_by_outfit', 'neutral', 'На Рябинине в этот момент рабочая одежда, сюртук не надет.', NULL, NULL, 'Тот, у церкви? В революцию усадьбу разбирали всем селом. Я вынес сюртук из пустого дома. У иных в селе и теперь графские вещи в сундуках лежат. К вашему приезду надел.', 'Фактическое место работы Рябинина; одежда и инструмент берутся из партии.', 'Сюртук взят из опустевшей усадьбы четырнадцать лет назад, сохранён в сундуке и надет ради встречи нового председателя.', 'Без гордости и стыда сообщить факт села; связать пролог с одеждой в сундуках.', '«Тот» относится к сюртуку в прологе. Не показывать грабёж и не придумывать судьбу графской семьи.', 'manual/characters/former-elder.md', 1, NULL, 0, 43);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.first_meeting.field.chairman', 'scene.elder.first_meeting', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'chairman', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Поле снято. Теперь надо решить, где что ставить.', 'Фактическое место работы Рябинина; одежда и инструмент берутся из партии.', 'Председатель уже снял резервное поле и решает, как размечать село.', 'Показать размен места, не присвоив решение председателя.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.first_meeting.layout.access', 'scene.elder.first_meeting', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'Согласие посмотреть предложенную разметку; показан контур access; фактическое место подходит строке.', NULL, NULL, 'Колышки без дороги простоят. Стройка — нет. Сначала оставьте повозке путь, потом ставьте на нём людей с брёвнами.', 'Фактическое место работы Рябинина; одежда и инструмент берутся из партии.', 'Председатель уже снял резервное поле и решает, как размечать село. Вариант допустим только при факте: Согласие посмотреть предложенную разметку; показан контур access; фактическое место подходит строке.', 'Показать размен места, не присвоив решение председателя.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 107);
