INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.introduction.opening.elder', 'scene.elder.introduction', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', 'chairman', 'Председатель и бывший староста знакомятся на его работе; уважительное «вы», без постоянного имени.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Был. Теперь работаю со всеми. Вы о селе спросить хотели?', 'Первое знакомство на фактической работе бывшего старосты; разговор доступен до и после снятия поля.', 'Бывший староста подтверждает роль и открыт к разговору.', 'Показать человека и следующий уместный шаг без обязательного порядка действий.', 'Нет фиксированного имени в речи; знакомство не равняется совету о разметке.', 'manual/texts/elder-introduction-quest.md', 1, 1, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.introduction.purpose.chairman', 'scene.elder.introduction', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'chairman', 'elder', 'Председатель и бывший староста знакомятся на его работе; уважительное «вы», без постоянного имени.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Да. С чего здесь разумнее начать?', 'Первое знакомство на фактической работе бывшего старосты; разговор доступен до и после снятия поля.', 'Председатель просит первый ориентир, не отдавая решение.', 'Показать человека и следующий уместный шаг без обязательного порядка действий.', 'Нет фиксированного имени в речи; знакомство не равняется совету о разметке.', 'manual/texts/elder-introduction-quest.md', 1, 1, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.introduction.quest.summary', 'scene.elder.introduction', 'scene', 'journal', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'neutral', NULL, NULL, NULL, 'Найти бывшего старосту и поговорить с ним о селе.', 'Первое знакомство на фактической работе бывшего старосты; разговор доступен до и после снятия поля.', 'Суть отдельной квестовой записи «Знакомство со старостой».', 'Показать человека и следующий уместный шаг без обязательного порядка действий.', 'Нет фиксированного имени в речи; знакомство не равняется совету о разметке.', 'manual/texts/elder-introduction-quest.md', 1, 1, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.last_advice.handoff', 'scene.elder.last_advice', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'fact:three_specialists_working', NULL, NULL, 'Что знал — говорил. Теперь у вас есть кого спрашивать точнее. Значит, не зря расчерчивали.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'В хозяйстве работают агроном, зоотехник и счетовод; роль старого советчика окончена. Вариант допустим только при факте: fact:three_specialists_working', 'Передать право более точного совета работающим специалистам.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 4, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.own_name.answer.elder', 'scene.elder.own_name', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Не от меня зависит. Хотите снова спрашивать — сначала сами скажите, чьё было решение.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Председатель сослался на Рябинина перед жителем и переложил на него ответственность за своё решение.', 'Назвать ответственность каждого участника без насмешки и наказания за совет.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.own_name.opening.elder', 'scene.elder.own_name', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Совет я давал вам. Теперь моё имя ходит по дворам и отвечает без меня. Так больше не пойдёт.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Председатель сослался на Рябинина перед жителем и переложил на него ответственность за своё решение.', 'Назвать ответственность каждого участника без насмешки и наказания за совет.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.own_name.question.chairman', 'scene.elder.own_name', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'chairman', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Что вы хотите услышать?', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Председатель сослался на Рябинина перед жителем и переложил на него ответственность за своё решение.', 'Назвать ответственность каждого участника без насмешки и наказания за совет.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.restore_talk.answer.deflect', 'scene.elder.restore_talk', 'scene', 'choice', NULL, NULL, NULL, NULL, 'chairman', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', 'answer', NULL, 'neutral', NULL, NULL, NULL, 'Людям нужен был ответ.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Председатель сам нашёл Рябинина на работе после испорченных отношений.', 'Дать игроку настоящую альтернативу без скрытого штрафа.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 11);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.restore_talk.answer.own', 'scene.elder.restore_talk', 'scene', 'choice', NULL, NULL, NULL, NULL, 'chairman', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', 'answer', NULL, 'neutral', NULL, NULL, NULL, 'Вместо ответа прозвучало ваше имя. Решение было моё.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Председатель сам нашёл Рябинина на работе после испорченных отношений.', 'Дать игроку настоящую альтернативу без скрытого штрафа.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.restore_talk.reply.deflect', 'scene.elder.restore_talk', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'Выбран answer.deflect.', NULL, NULL, 'Вот и отвечайте своим именем. Моё оставьте мне.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Председатель сам нашёл Рябинина на работе после испорченных отношений. Вариант допустим только при факте: Выбран answer.deflect.', 'Назвать ответственность каждого участника без насмешки и наказания за совет.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 21);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.restore_talk.reply.own', 'scene.elder.restore_talk', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'Выбран answer.own; обычные отношения не закрывают разговор.', NULL, NULL, 'Теперь верно сказано. Когда понадобится — спросите.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Председатель сам нашёл Рябинина на работе после испорченных отношений. Вариант допустим только при факте: Выбран answer.own; обычные отношения не закрывают разговор.', 'Назвать ответственность каждого участника без насмешки и наказания за совет.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.warnings.hay_before_snow', 'scene.elder.warnings', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'fact:elder_warn_hay_before_snow', NULL, NULL, 'Трава на корню — не зимний запас. Скосите до снега: сено и в кучах сохранится.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'На лугу осталась нескошенная трава за месяц до устойчивого снега; уже скошенные кучи сена остаются запасом.', 'Предупредить о видимом и ещё исправимом риске.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 4, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.warnings.late_harvest', 'scene.elder.warnings', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'fact:elder_warn_late_harvest', NULL, NULL, 'Урожай созрел, а убрать ещё не успели. До конца уборки мало времени; посмотрите, хватает ли людей и подвод.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Созревшая культура остаётся в поле перед концом уборки; люди и подводы ещё могут успеть.', 'Предупредить о видимом и ещё исправимом риске.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/texts/elder-explains-clarity.md', 4, NULL, 0, 42);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.warnings.next_seed', 'scene.elder.warnings', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'fact:elder_warn_next_seed', NULL, NULL, 'Для будущего сева запаса не хватает. Посмотрите семенной фонд и поля на будущий год: что сеять, ещё можно поправить.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Разложены поля следующего года, но посевного запаса на эту раскладку не хватает; её ещё можно изменить.', 'Предупредить о видимом и ещё исправимом риске.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/texts/elder-explains-clarity.md', 4, NULL, 0, 41);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.warnings.no_access', 'scene.elder.warnings', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'Размеченная стройка без подъезда, исправление ещё не начато.', NULL, NULL, 'Стены тут поместятся. Теперь покажите, откуда к ним придёт первая повозка.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Рябинин замечает исправимую недоработку до потери; он говорит лишь после знакомства. Вариант допустим только при факте: Размеченная стройка без подъезда, исправление ещё не начато.', 'Предупредить о видимом и ещё исправимом риске.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.warnings.sowing_window', 'scene.elder.warnings', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'fact:elder_warn_sowing_window', NULL, NULL, 'Срок сева подходит, а поле пустое. Проверьте наряд и семена: поздний сев даст меньше урожая.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Окно сева назначенной культуры близко к концу, а работу на поле ещё не начали; поздний сев снизит урожай.', 'Предупредить о видимом и ещё исправимом риске.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/texts/elder-explains-clarity.md', 5, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.warnings.work_due', 'scene.elder.warnings', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'Видимая работа ещё не началась перед её сроком; подстановки заполнены из партии.', NULL, NULL, 'Срок поджимает: {work_name}. А {place_name} ещё пустует. Дальше погода будет решать вместо вас.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Рябинин замечает исправимую недоработку до потери; он говорит лишь после знакомства. Вариант допустим только при факте: Видимая работа ещё не началась перед её сроком; подстановки заполнены из партии.', 'Предупредить о видимом и ещё исправимом риске.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/characters/former-elder.md', 2, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.elder.warnings.zyab', 'scene.elder.warnings', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'elder', NULL, 'Председатель и Рябинин: рабочее уважительное «вы», совет не приказ.', NULL, NULL, 'neutral', 'fact:elder_warn_zyab_started', NULL, NULL, 'Стерню сейчас пашут под весенний сев. Это зябь: весной останется забороновать поле и сеять.', 'Сцена произносится только по зарегистрированному поводу и фактам партии.', 'Осенью после уборки свободные руки действительно пашут стерню под яровые будущего года; игрок не включает зябь кнопкой.', 'Предупредить о видимом и ещё исправимом риске.', 'Сохранить уважительное «вы», смысл и отсутствие приказа; не добавлять новых условий.', 'manual/texts/elder-explains-clarity.md', 4, NULL, 0, 43);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.office.fire.chairman', 'scene.ending.office.fire', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'chairman', 'resident', 'Председатель отвечает фактически присутствующему собеседнику.', NULL, NULL, 'neutral', 'always', NULL, NULL, 'Здесь были книги, наряды, печать... Где теперь искать хоть одну запись?', 'Сцена «Сгорел кабинет». Голос: Председатель. Условие: always.', 'Пожар кабинета и судьба учётных записей.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.office.fire.resident', 'scene.ending.office.fire', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'resident', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'always_after_chairman', NULL, NULL, 'Огонь и до бумаг добрался. Теперь многое придётся вспоминать по людям.', 'Сцена «Сгорел кабинет». Голос: Житель. Условие: always_after_chairman.', 'Пожар кабинета и судьба учётных записей.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always_after_chairman; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.office.removal.judge', 'scene.ending.office.removal', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'judge', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'always_after_case_record', NULL, NULL, 'Материалы о пожаре и утрате учёта рассмотрены. Решение — отстранить вас от должности председателя колхоза. Восстановление хозяйства передадут другому человеку.', 'Сцена «Ревизия, дело, отстранение после пожара». Голос: Судья. Условие: always_after_case_record.', 'Проверка и отстранение в сутки пожара.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always_after_case_record; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.office.removal.zhernova', 'scene.ending.office.removal', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'zhernova', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'always', NULL, NULL, 'Кабинет уничтожен вместе с книгами и печатью. Прежние записи проверить уже нельзя.', 'Сцена «Ревизия, дело, отстранение после пожара». Голос: Жернова. Условие: always.', 'Проверка и отстранение в сутки пожара.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.trial.case.chairman', 'scene.ending.trial.case', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'chairman', 'investigator', 'Председатель отвечает фактически присутствующему собеседнику.', NULL, NULL, 'neutral', 'always_after_open', NULL, NULL, 'Запишите: я отвечал за хозяйство. О работе могут рассказать люди, которые её делали.', 'Сцена «Дело: допрос председателя». Голос: Председатель. Условие: always_after_open.', 'Запись слов председателя в районном деле.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always_after_open; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.trial.case.open', 'scene.ending.trial.case', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'investigator', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'always', NULL, NULL, 'В материалах есть сводка района и запись комиссии. Перед отправкой дела в суд я обязан записать ваши слова.', 'Сцена «Дело: допрос председателя». Голос: Следователь. Условие: always.', 'Запись слов председателя в районном деле.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.trial.case.return', 'scene.ending.trial.case', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'investigator', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'always_after_chairman', NULL, NULL, 'Так и запишу. Их слова приложим отдельно.', 'Сцена «Дело: допрос председателя». Голос: Следователь. Условие: always_after_chairman.', 'Запись слов председателя в районном деле.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always_after_chairman; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 30);
