INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.village.liquidation.district', 'scene.ending.village.liquidation', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'district_rep', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'always', NULL, NULL, 'Два года подряд жителей меньше сорока. Район принял решение: отдельное хозяйство ликвидировать, земли и оставшиеся дворы присоединить к соседнему. Как люди будут жить дальше, будем решать с каждым двором.', 'Сцена «Хозяйство ликвидируют». Голос: Представитель района. Условие: always.', 'Ликвидация отдельного хозяйства, не исчезновение людей.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.village.warning_report.district', 'scene.ending.village.warning_report', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'district_rep', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'always', NULL, NULL, 'На этот поворот года население хозяйства — {resident_count}. Если и через год жителей останется меньше сорока, район будет решать вопрос о присоединении села к соседнему хозяйству.', 'Сцена «Сводка района: село убывает». Голос: Представитель района. Условие: always.', 'Первое предупреждение об убыли без решения о ликвидации.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие always; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 2, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.ending.village.warning_rumour.resident', 'scene.ending.village.warning_rumour', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'resident', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'adult_knows_report', NULL, NULL, 'Пустых дворов стало больше. Но в обжитых ещё топят печи.', 'Сцена «Разговоры в селе об убыли». Голос: Житель. Условие: adult_knows_report.', 'Отклик жителя на дошедшую новость.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие adult_knows_report; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_offer.karasev', 'scene.era.first_transition_offer', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'karasev', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=karasev', NULL, NULL, 'Привёз предложение района: новый статус, укрупнение, целевые фонды. Третий год вы держите нужный уровень. Ответ теперь за вами.', 'Сцена «Район предлагает переход». Голос: Карасёв. Условие: district_face=karasev.', 'Район предлагает переход; игрок отвечает карточкой.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=karasev; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_offer.korenev', 'scene.era.first_transition_offer', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'korenev', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=korenev', NULL, NULL, 'Хозяйство держит нужный уровень третий год. Район предлагает новый статус, укрупнение и целевые фонды. Решение за вами. Но подумайте, кто возьмёт на себя новую работу.', 'Сцена «Район предлагает переход». Голос: Коренев. Условие: district_face=korenev.', 'Район предлагает переход; игрок отвечает карточкой.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=korenev; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 2, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_offer.polushkina', 'scene.era.first_transition_offer', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'polushkina', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=polushkina', NULL, NULL, 'По трём годам хозяйство проходит условия. В письме района — новый статус, укрупнение и целевые фонды. Остаётся записать ваш ответ.', 'Сцена «Район предлагает переход». Голос: Полушкина. Условие: district_face=polushkina.', 'Район предлагает переход; игрок отвечает карточкой.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=polushkina; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_offer.stozharov', 'scene.era.first_transition_offer', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'stozharov', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=stozharov', NULL, NULL, 'Третий год хозяйство держится. Район предлагает новый статус, укрупнение и целевые фонды. Прежде чем отвечать, прикиньте, кому поручите новые дела.', 'Сцена «Район предлагает переход». Голос: Стожаров. Условие: district_face=stozharov.', 'Район предлагает переход; игрок отвечает карточкой.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=stozharov; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_offer.zhernova', 'scene.era.first_transition_offer', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'zhernova', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=zhernova', NULL, NULL, 'Три года нужный уровень удержан. Район предлагает новый статус, укрупнение и целевые фонды. Решать вам; бумаги уже готовы к обоим ответам.', 'Сцена «Район предлагает переход». Голос: Жернова. Условие: district_face=zhernova.', 'Район предлагает переход; игрок отвечает карточкой.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=zhernova; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_refusal.karasev', 'scene.era.first_transition_refusal', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'karasev', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=karasev', NULL, NULL, 'Записал отказ. Район вернётся к вопросу не раньше чем через три года. Я пока уберу этот лист.', 'Сцена «Отказ от перехода». Голос: Карасёв. Условие: district_face=karasev.', 'Район фиксирует отказ и срок следующего предложения.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=karasev; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 2, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_refusal.korenev', 'scene.era.first_transition_refusal', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'korenev', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=korenev', NULL, NULL, 'Отказ записан. В нынешнем укладе остаётесь. Раньше трёх лет район к этому вопросу не вернётся.', 'Сцена «Отказ от перехода». Голос: Коренев. Условие: district_face=korenev.', 'Район фиксирует отказ и срок следующего предложения.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=korenev; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_refusal.polushkina', 'scene.era.first_transition_refusal', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'polushkina', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=polushkina', NULL, NULL, 'Отказ отмечен. Следующее предложение возможно не раньше чем через три года.', 'Сцена «Отказ от перехода». Голос: Полушкина. Условие: district_face=polushkina.', 'Район фиксирует отказ и срок следующего предложения.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=polushkina; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_refusal.stozharov', 'scene.era.first_transition_refusal', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'stozharov', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=stozharov', NULL, NULL, 'Оставайтесь в нынешнем укладе. Район вернётся с предложением не раньше чем через три года.', 'Сцена «Отказ от перехода». Голос: Стожаров. Условие: district_face=stozharov.', 'Район фиксирует отказ и срок следующего предложения.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=stozharov; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.era.first_transition_refusal.zhernova', 'scene.era.first_transition_refusal', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'zhernova', 'chairman', 'Говорящий обращается к председателю по фактическому поводу сцены.', NULL, NULL, 'neutral', 'district_face=zhernova', NULL, NULL, 'Отказ внесён в запись. Нынешний порядок сохраняется. Повторить предложение район сможет не раньше чем через три года.', 'Сцена «Отказ от перехода». Голос: Жернова. Условие: district_face=zhernova.', 'Район фиксирует отказ и срок следующего предложения.', 'Назвать последствие человеческим голосом, без угрозы и морали.', 'Сохранить фактическое условие district_face=zhernova; не переносить эту строку на другого говорящего или другую стадию.', 'manual/texts/epoch1-ending-lines.md', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.answer.general', 'scene.family.before_distribution', 'scene', 'choice', NULL, NULL, NULL, NULL, 'chairman', 'member', 'Председатель принимает общее правило для всех подходящих дворов.', 'answer', NULL, 'neutral', 'Склад позволяет включить общее правило для дворов у порога минимального пайка.', 'changed', 'scene.family.before_distribution.opening.queue', 'Кто просел до минимума, получит паёк. Не только вы.', 'Второй вариант ответа; виден только если фактический склад может обеспечить общее правило.', 'Помощь по одинаковому правилу всем семьям у порога.', 'Назвать не конкретный двор, а проверяемый общий критерий.', 'Сохранить условность «кто просел до минимума» и противопоставление личной помощи.', 'manual/quests/family-thread.md#разговор-до-выдачи', 2, NULL, 0, 31);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.answer.personal', 'scene.family.before_distribution', 'scene', 'choice', NULL, NULL, NULL, NULL, 'chairman', 'member', 'Председатель отвечает конкретному пришедшему взрослому; решение распространяется только на его двор.', 'answer', NULL, 'neutral', NULL, 'changed', 'scene.family.before_distribution.opening.queue', 'Включу паёк вашему двору уже сейчас.', 'Первый вариант ответа, всегда доступен; действие действительно включает паёк одному двору.', 'Личная помощь выбранной семье до общей выдачи.', 'Зафиксировать личное решение, а не обещание на потом.', 'Сохранить «вашему двору» и «сейчас»; не обещать паёк остальным.', 'manual/quests/family-thread.md#разговор-до-выдачи', 2, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.answer.premium', 'scene.family.before_distribution', 'scene', 'choice', NULL, NULL, NULL, NULL, 'chairman', 'member', 'Председатель называет заслуженную, но ещё не выданную премию выбранной семье.', 'answer', NULL, 'neutral', 'У семьи есть реальный заслуживающий премии поступок; премия ещё не выдана.', 'changed', 'scene.family.before_distribution.opening.queue', 'За {real_deed} вашей семье положена премия. Выдадим сейчас.', 'Третий вариант ответа; {real_deed} — грамматически готовое словосочетание после «за», только о фактическом поступке семьи.', 'Премия выдаётся за уже совершённое дело, не как замаскированный паёк.', 'Назвать основание выплаты и принять немедленное решение.', 'Не придумывать заслугу и не опускать основание; подстановка должна согласовываться с предлогом «за».', 'manual/quests/family-thread.md#разговор-до-выдачи', 2, NULL, 0, 32);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.answer.unchanged', 'scene.family.before_distribution', 'scene', 'choice', NULL, NULL, NULL, NULL, 'chairman', 'member', 'Председатель отвечает без изменения обычного порядка.', 'answer', NULL, 'neutral', NULL, 'unchanged', 'scene.family.before_distribution.opening.queue', 'До выдачи порядок не меняю.', 'Четвёртый вариант ответа, всегда доступен; семья получает обычную выдачу по действующим правилам.', 'Председатель отказывает в раннем изменении порядка, не отказывая семье в обычной выдаче.', 'Сделать отказ ясным и коротким, без обвинения семьи.', 'Сохранить срок «до выдачи»; не превращать в постоянный отказ в пайке.', 'manual/quests/family-thread.md#разговор-до-выдачи', 2, NULL, 0, 33);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.backdrop', 'scene.family.before_distribution', 'scene', 'backdrop', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'neutral', NULL, NULL, NULL, 'Один двор просит помочь сейчас; рядом есть другие, которым не легче.', 'Авторская подложка сцены «До выдачи», игроку не показывается. Семья выбрана из фактической партии.', 'Нужда одного двора ставит вопрос об общем правиле для других дворов.', 'Ограничить разговор четырьмя реальными решениями без голодной трагедии.', 'Не превращать детей в средство давления и не придумывать беду другим дворам.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 1);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.memory.general', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'memory_member', NULL, 'Доступный взрослый того же двора или родственной ветви вспоминает общее правило после их просьбы.', NULL, NULL, 'neutral', 'Сохранён исход answer.general.', NULL, NULL, 'После нашего разговора паёк пошёл всем.', 'Короткая первая реплика позднего возврата семьи; «всем» означает подходящие дворы, не всех жителей.', 'После обращения семьи помощь стали получать все дворы у порога.', 'Привязать поздний возврат к принятому общему правилу.', 'Сохранить причинную последовательность разговора и решения; не приписывать семье принятие правила.', 'manual/quests/family-thread.md#что-запоминается-для-следующих-сцен', 1, NULL, 0, 51);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.memory.personal', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'memory_member', NULL, 'Доступный взрослый того же двора или родственной ветви вспоминает личную помощь председателя.', NULL, NULL, 'neutral', 'Сохранён исход answer.personal.', NULL, NULL, 'Вы тогда помогли нашему двору отдельно.', 'Короткая первая реплика позднего возврата семьи, не часть разговора Эпохи I.', 'Председатель помог только этому двору.', 'Привязать поздний возврат к действительно записанному исходу.', 'Сохранить «нашему двору» и «отдельно»; не утверждать помощи другим.', 'manual/quests/family-thread.md#что-запоминается-для-следующих-сцен', 1, NULL, 0, 50);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.memory.premium', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'memory_member', NULL, 'Доступный взрослый того же двора или родственной ветви вспоминает заслуженную премию.', NULL, NULL, 'neutral', 'Сохранён исход answer.premium.', NULL, NULL, 'Мы тогда получили своё не по просьбе, а за дело.', 'Короткая первая реплика позднего возврата семьи, без новой выплаты.', 'Премия была заработана до просьбы и затем выдана.', 'Сохранить в семейной памяти основание премии, а не вторую награду.', 'Не называть премию подачкой и не обещать повторной выплаты.', 'manual/quests/family-thread.md#что-запоминается-для-следующих-сцен', 1, NULL, 0, 52);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.memory.usual', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'memory_member', NULL, 'Доступный взрослый того же двора или родственной ветви вспоминает обычную выдачу.', NULL, NULL, 'neutral', 'Выбран answer.unchanged либо срок истёк без разговора.', NULL, NULL, 'Мы тогда дотянули до выдачи своим двором.', 'Короткая первая реплика позднего возврата семьи; срок может истечь вообще без разговора.', 'Семья получила обычную выдачу без ранней помощи.', 'Объединить два пути к одному фактическому исходу.', 'Не подразумевать, что председатель разговаривал с семьёй при вышедшем сроке.', 'manual/quests/family-thread.md#что-запоминается-для-следующих-сцен', 1, NULL, 0, 53);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.opening.bread', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'member', 'chairman', 'Взрослый член выбранной семьи обращается к председателю с просьбой до очередной выдачи.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'До выдачи мы дотянем. Только дети начали хлеб на завтра считать сегодня.', 'Первое высказывание в кабинете; у выбранной семьи действительно есть ребёнок. Без показа голода и плачущих детей.', 'Семья может дождаться выдачи, но запас уже тревожно мал.', 'Дать человеческую причину просьбы, не обвиняя председателя.', 'Сохранить уверенное «дотянем» и тревогу о завтрашнем хлебе; не усиливать до угрозы голодной смерти.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.opening.queue', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'member', 'chairman', 'Тот же взрослый член семьи признаёт общее правило очереди, но говорит о своём дворе.', NULL, NULL, 'neutral', NULL, NULL, 'scene.family.before_distribution.opening.bread', 'На складе сказали: очередь общая. Я не спорю. Только пустая полка у каждого своя.', 'Вторая реплика открытия непосредственно перед вариантами ответа; говорящий не предъявляет права перед другими дворами.', 'Общая очередь не отменяет разной нужды семей.', 'Завершить просьбу без упрёка соседям и без торга.', 'Сохранить контраст общей очереди и отдельной полки; не менять его на обвинение кладовщика.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.reply.general', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'member', 'chairman', 'Взрослый член семьи отвечает после принятого общего правила.', NULL, NULL, 'neutral', 'Выбран answer.general.', NULL, 'scene.family.before_distribution.answer.general', 'Значит, просьба была первая, а паёк получат все.', 'Ответ на общую помощь; «все» означает только все дворы у принятого порога, не всё население.', 'Проситель осознаёт, что помощь распространилась дальше его двора.', 'Подтвердить принятое правило, не присваивая себе заслугу.', 'Сохранить различие «первая просьба» и «всем подходящим»; не расширять до всех жителей.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 41);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.reply.personal', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'member', 'chairman', 'Взрослый член семьи отвечает после личной помощи их двору.', NULL, NULL, 'neutral', 'Выбран answer.personal.', NULL, 'scene.family.before_distribution.answer.personal', 'Спасибо. За чужой двор я не отвечу, а свой до выдачи доведу.', 'Ответ после решения о личном пайке; говорящий не распоряжается другими дворами.', 'Семья благодарит и берёт ответственность за собственный двор.', 'Закрыть разговор без требования помочь соседям тем же способом.', 'Сохранить благодарность без долгового обещания или укора соседям.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.reply.premium', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'member', 'chairman', 'Взрослый член семьи принимает заслуженную премию.', NULL, NULL, 'neutral', 'Выбран answer.premium.', NULL, 'scene.family.before_distribution.answer.premium', 'За дело возьмём. И детям скажу, чем заработано.', 'Ответ после премии за уже совершённое дело; в семье действительно есть ребёнок.', 'Семья принимает премию как признание труда, не как подачку.', 'Закрыть ветку премии достойно и конкретно.', 'Сохранить «за дело» и сообщение детям; не называть премию благотворительностью.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 42);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.family.before_distribution.reply.unchanged', 'scene.family.before_distribution', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'member', 'chairman', 'Взрослый член семьи принимает ясный ответ об обычной выдаче.', NULL, NULL, 'neutral', 'Выбран answer.unchanged.', NULL, 'scene.family.before_distribution.answer.unchanged', 'Значит, до выдачи — своим двором. Ответ ясен.', 'Ответ только после явного отказа менять порядок; при вышедшем сроке разговора и этой реплики нет.', 'Семья понимает, что до обычной выдачи рассчитывает на себя.', 'Закрыть разговор без унижения или скрытого штрафа.', 'Сохранить спокойную дистанцию, не превращать строку в благодарность или угрозу.', 'manual/quests/family-thread.md#разговор-до-выдачи', 1, NULL, 0, 43);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_leak_return.opening.new_place', 'scene.night_hunt.distiller_leak_return', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'storekeeper', 'chairman', 'Работник склада сообщает известное место новой передачи.', NULL, NULL, 'neutral', 'После повторной утечки; работнику известно новое наблюдение передачи.', NULL, 'scene.night_hunt.distiller_leak_return.opening.through_yard', 'Вчера передача была уже {place}. Там и посмотрите вечером.', 'Дополнение дневного доклада перед новой вечерней засадой, не вывод из одной недостачи.', 'Названо новое место известной свидетелю передачи; старый двор не считается верным автоматически.', 'Дать маршрут следующего поиска без раскрытия тайной роли.', 'Показывать только при действительно известном работнику наблюдении. Повторная утечка сама адреса не раскрывает.', 'manual/texts/night-hunt-scenes.md#склад-остался-проходным--повторная-утечка', 1, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_leak_return.opening.through_yard', 'scene.night_hunt.distiller_leak_return', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'storekeeper', 'chairman', 'Работник склада сообщает председателю о новой утечке после поимки самогонщика.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Того у ворот взяли, а мешки опять ушли. Значит, человек сменился, а склад так и остался проходным двором.', 'Днём в кабинете после новой фактической утечки при всё ещё открытом складе; самогонщик уже был пойман у ворот.', 'Поимка убрала одного продавца, но не закрыла путь сырья со склада к следующему.', 'Перенести внимание игрока с личности пойманного на охрану склада без доноса на конкретного работника.', 'Сохранить противопоставление сменившегося человека и неизменившегося проходного двора; «проходной двор» относится к складу.', 'manual/texts/night-hunt-scenes.md#склад-остался-проходным--повторная-утечка', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.answer.decline', 'scene.night_hunt.distiller_report', 'scene', 'choice', NULL, NULL, NULL, NULL, 'chairman', 'storekeeper', 'Председатель пока отказывается от вечерней засады.', 'answer', NULL, 'neutral', NULL, NULL, 'scene.night_hunt.distiller_report.opening.meeting', 'Сегодня вечером не пойду.', 'Второй из двух ответов председателя в дневном разговоре.', 'Председатель не берёт нынешнюю засаду, но причина в мире остаётся.', 'Отложить действие без наказания и без обещания конкретной следующей даты.', 'Сохранить прямоту и вечер как время предлагаемой засады.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 1, NULL, 0, 31);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.answer.take', 'scene.night_hunt.distiller_report', 'scene', 'choice', NULL, NULL, NULL, NULL, 'chairman', 'storekeeper', 'Председатель берёт вечернюю засаду на себя.', 'answer', NULL, 'neutral', NULL, NULL, 'scene.night_hunt.distiller_report.opening.meeting', 'Сегодня вечером, как стемнеет, проверю на месте.', 'Первый из двух ответов председателя в дневном разговоре.', 'Председатель обещает прийти после наступления темноты, но до ночного отбоя.', 'Назначить вечернюю засаду без лунного календаря и без обещания ночного разговора.', 'Сохранить оба признака времени: сегодня вечером и после наступления темноты.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 1, NULL, 0, 30);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.opening.meeting', 'scene.night_hunt.distiller_report', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'storekeeper', 'chairman', 'Работник склада сообщает только то, что видел сам.', NULL, NULL, 'neutral', NULL, NULL, 'scene.night_hunt.distiller_report.opening.mice', 'Позавчера, уже затемно, {place} двое встретились. Один пришёл с пустыми руками, ушёл — уже не с пустыми. Я туда не полез. Моё дело склад удержать.', 'Тот же дневной разговор после показа листка выдач.', 'Работник передаёт известное ему место наблюдения у ворот определённого двора, не имя тайного самогонщика.', 'Дать место для вечерней проверки, не превращая наблюдение в готовое доказательство.', 'Сохранить противопоставление пустых рук до встречи и непустых после; «моё дело склад удержать» не является признанием в утечке.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 3, NULL, 0, 20);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.opening.mice', 'scene.night_hunt.distiller_report', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'storekeeper', 'chairman', 'Работник склада показывает председателю необъяснённую недостачу.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'На мышей я сперва списал. Только мышь нынче разборчивая: зерно берёт, мешок завязывает и со двора уносит.', 'Днём в кабинете; внизу листка выдач приписаны три мешка без накладной.', 'Недостача похожа не на порчу и не на грызунов, а на аккуратный вынос целых мешков.', 'Сообщить о хозяйственной дыре сухой наблюдательной шуткой, а не обвинением.', 'Сохранить образ разборчивой мыши, которая завязывает мешок и уносит его со двора.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.reply.decline', 'scene.night_hunt.distiller_report', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'storekeeper', 'chairman', 'Работник склада принимает отказ председателя без обиды.', NULL, NULL, 'neutral', 'Выбран answer.decline.', NULL, 'scene.night_hunt.distiller_report.answer.decline', 'Значит, ещё раз пересчитаю. Может, мешки сами образумятся.', 'После отказа председателя от нынешней вечерней засады.', 'Работник продолжит учёт, хотя понимает, что один пересчёт утечку не закроет.', 'Закрыть разговор хозяйственной досадой, а не упрёком игроку.', 'Сохранить шутку на стороне учёта: образумиться должны исчезающие мешки, не человек.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 1, NULL, 0, 41);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.night_hunt.distiller_report.reply.take', 'scene.night_hunt.distiller_report', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'storekeeper', 'chairman', 'Работник склада объясняет границу своего участия.', NULL, NULL, 'neutral', 'Выбран answer.take.', NULL, 'scene.night_hunt.distiller_report.answer.take', 'Место я назвал. Засветло дорогу запомните. Как стемнеет — дальше без меня.', 'После согласия председателя на вечернюю засаду.', 'Место уже названо в свидетельстве; работник советует запомнить дорогу засветло, не обещает несуществующее сопровождение.', 'Оставить перехват личным действием председателя без трусости и доносительства работника.', 'Сохранить вечер после темноты до отбоя, личный приход председателя и границу участия работника. Не добавлять метку или сопровождение.', 'manual/texts/night-hunt-scenes.md#кто-гонит--пропавшее-сырьё', 2, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.office_intro.affairs_notebook.acting', 'scene.start.office', 'scene', 'spoken_thought', 'acting', 'office', 'item', 'office_intro.affairs_notebook', 'chairman', NULL, NULL, NULL, 'office_intro.affairs_notebook', 'female', 'Выбран avatar.key=acting; опора office_intro.affairs_notebook.', NULL, NULL, 'Первое дело есть. Разберусь, какая помощь понадобится.', 'Первое знакомство с кабинетом; выбран avatar.key=acting. Автоматическое открытие тетради «Дела». Председатель сидит, время на паузе. Рабочий текст для показа, без TTS. Тетрадь открывается сама с кнопками; дополнительного клика нет.', 'Реакция выбранного председателя: Первое дело есть. Разберусь, какая помощь понадобится.', 'Передать взгляд и характер аватара через конкретную вещь, без нового задания.', 'Сохранить буквальный смысл и голос аватара; не добавлять объяснение портала, видимый мир за мутным стеклом или знание содержимого запертого ящика. Независимость от порядка кликов; не объявлять квест выполненным.', 'manual/texts/office-intro-full-corpus.md', 1, 1, 0, 818);
