INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.office_intro.window.villager', 'scene.start.office', 'scene', 'spoken_thought', 'villager', 'office', 'item', 'office_intro.window', 'chairman', NULL, NULL, NULL, 'office_intro.window', 'male', 'Выбран avatar.key=villager; опора office_intro.window.', NULL, NULL, 'Сквозь стекло двора не видно. Захочу посмотреть — придётся выйти.', 'Первое знакомство с кабинетом; выбран avatar.key=villager. Мутное окно. Председатель сидит, время на паузе. Рабочий текст для показа, без TTS.', 'Реакция выбранного председателя: Сквозь стекло двора не видно. Захочу посмотреть — придётся выйти.', 'Передать взгляд и характер аватара через конкретную вещь, без нового задания.', 'Сохранить буквальный смысл и голос аватара; не добавлять объяснение портала, видимый мир за мутным стеклом или знание содержимого запертого ящика. Независимость от порядка кликов; не объявлять квест выполненным.', 'manual/texts/office-intro-full-corpus.md', 1, 1, 0, 116);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.office_intro.window.worker', 'scene.start.office', 'scene', 'spoken_thought', 'worker', 'office', 'item', 'office_intro.window', 'chairman', NULL, NULL, NULL, 'office_intro.window', 'male', 'Выбран avatar.key=worker; опора office_intro.window.', NULL, NULL, 'Окно мутное, но свет пропускает. Уже хорошо.', 'Первое знакомство с кабинетом; выбран avatar.key=worker. Мутное окно. Председатель сидит, время на паузе. Рабочий текст для показа, без TTS.', 'Реакция выбранного председателя: Окно мутное, но свет пропускает. Уже хорошо.', 'Передать взгляд и характер аватара через конкретную вещь, без нового задания.', 'Сохранить буквальный смысл и голос аватара; не добавлять объяснение портала, видимый мир за мутным стеклом или знание содержимого запертого ящика. Независимость от порядка кликов; не объявлять квест выполненным.', 'manual/texts/office-intro-full-corpus.md', 1, 1, 0, 216);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.perk.talk_to_people_close.thought', 'scene.perk.talk_to_people_close', 'scene', 'narration', NULL, NULL, NULL, NULL, 'chairman', NULL, 'Председатель мысленно отмечает конкретный результат только что прошедшего разговора.', NULL, NULL, 'neutral', 'Первый разговор с результатом; quest_perk_03 закрылся.', NULL, NULL, 'Дело сдвинулось не приказом. Значит, услышали.', 'Внутренняя мысль после первого разговора, который привёл к согласию, снятию просьбы или улаженной ссоре.', 'Дело изменилось после разговора, но одна удача не делает председателя убедительным навсегда.', 'Отметить человеческий смысл уже рассчитанного закрытия перка, не выдавая новый результат самой репликой.', 'Не называть харизму и не обещать постоянной способности убеждать.', 'manual/texts/perk-entry-quests.md#поговорить-с-людьми', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.perk.talk_to_people_open.thought', 'scene.perk.talk_to_people_open', 'scene', 'narration', NULL, NULL, NULL, NULL, 'chairman', NULL, 'Председатель мысленно оценивает результат только что прошедшего разговора.', NULL, NULL, 'neutral', 'Первый разговор без результата; quest_perk_03 открылся.', NULL, NULL, 'Слова были мои. Решение осталось прежним. Значит, разговора не получилось.', 'Внутренняя мысль после первого безрезультатного разговора; звучит в уже идущем диалоге без новой постановки.', 'Собеседник сохранил своё решение; дело не изменилось.', 'Дать игроку человеческую формулировку первого неудачного опыта разговора без штрафа и обвинения жителя.', 'Не добавлять новую сцену разговора, не понижать метрику и не называть собеседника упрямым.', 'manual/texts/perk-entry-quests.md#поговорить-с-людьми', 1, NULL, 0, 10);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.school_fears.birds_settle.notebook', 'scene.school_fears.birds_settle', 'scene', 'document', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'neutral', 'society_outcome=observation', NULL, NULL, 'Птицы сели все сразу. На уроке сказали — на ночёвку. Старшие сказали — потому что наговорились. Проверить не удалось.', '«Чёрное облако», сцена «Птицы сели»; строка авторского источника 375.', 'После развязки дети всё ещё могут искать близости взрослого.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 40);
