INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.school_fears.words_without_owner.teacher_three_answers', 'scene.school_fears.words_without_owner', 'scene', 'dialogue', NULL, NULL, NULL, NULL, 'teacher', NULL, 'Присутствующие дети и взрослые говорят между собой.', NULL, NULL, 'neutral', NULL, NULL, NULL, 'Записали три версии. Первая школьная работа, где три разных ответа и ни одной двойки.', '«Чёрное облако», сцена «Слова без хозяйки»; строка авторского источника 356.', 'Роль выбывшей жительницы никому не передаётся.', 'Передать живой голос и фактический этап расследования, не подтверждая мистику.', 'Не менять секрет, случайный состав, пол участника или уважительный тон к детскому страху.', 'manual/texts/school-fears-bird-scenes.md', 1, NULL, 0, 40);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.acting.t1', 'scene.start.prologue', 'scene', 'spoken_thought', 'acting', 'prologue', 'scene', 'scene.start.prologue#t1', 'chairman', NULL, NULL, NULL, 'start.prologue.t1', 'female', 'Выбран avatar.key = acting; адрес пролога 0:06.', NULL, NULL, 'Какая-то чертовщина. Лошадь тоже неладное чует.', 'Дорожный пролог, 0:06. В плотном тумане одна и та же берёза прошла слева второй раз. Внутренняя мысль аватара «Временная»; показывается субтитром и озвучивается.', 'Председатель замечает невозможное повторение дороги, но не понимает переход.', 'Сразу дать голос выбранного аватара и показать странность без объяснения.', 'Практичная речь опытной руководительницы; сохранить женский род, не превращать заботу в образ матери села. Не называть портал и не объяснять природу тумана.', 'ai/prologue-avatar-thoughts-draft.md#11-временная', 2, 2, 0, 108);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.acting.t2', 'scene.start.prologue', 'scene', 'spoken_thought', 'acting', 'prologue', 'scene', 'scene.start.prologue#t2', 'chairman', NULL, NULL, NULL, 'start.prologue.t2', 'female', 'Выбран avatar.key = acting; адрес пролога 0:29.', NULL, 'scene.start.prologue.acting.t1', 'Доехали легко только потому, что зима была малоснежной. В обычную весну эта дорога отрежет село от района.', 'Дорожный пролог, 0:29. После взгляда назад видна обычная мокрая дорога; на экране уже указан апрель 1931 года. Внутренняя мысль аватара «Временная»; показывается субтитром и озвучивается.', 'Малоснежная зима объясняет необычно лёгкий путь и будущую весеннюю распутицу.', 'Объяснить игроку различие первой и обычной весны как знание героя, а не подсказку механики.', 'Практичная речь опытной руководительницы; сохранить женский род, не превращать заботу в образ матери села. Сохранить причинную связь: мало снега — мало талой воды — дорога временно держит.', 'ai/prologue-avatar-thoughts-draft.md#11-временная', 2, 2, 0, 208);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.acting.t3', 'scene.start.prologue', 'scene', 'spoken_thought', 'acting', 'prologue', 'scene', 'scene.start.prologue#t3', 'chairman', NULL, NULL, NULL, 'start.prologue.t3', 'female', 'Выбран avatar.key = acting; адрес пролога 0:48.', NULL, 'scene.start.prologue.acting.t2', 'Кладбище рядом с дорогой. Надо будет узнать, кто следит за отворотком и оградой.', 'Дорожный пролог, 0:48. Кладбище видно за голыми деревьями слева от дороги. Внутренняя мысль аватара «Временная»; показывается субтитром и озвучивается.', 'Кладбище показывает, что село и его связи старше колхоза.', 'Показать отношение аватара к прошлому незнакомого или родного села.', 'Практичная речь опытной руководительницы; сохранить женский род, не превращать заботу в образ матери села. Не приписывать незнакомым жителям мысли, память или намерения.', 'ai/prologue-avatar-thoughts-draft.md#11-временная', 2, 2, 0, 308);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.acting.t4', 'scene.start.prologue', 'scene', 'spoken_thought', 'acting', 'prologue', 'scene', 'scene.start.prologue#t4', 'chairman', NULL, NULL, NULL, 'start.prologue.t4', 'female', 'Выбран avatar.key = acting; адрес пролога 1:47.', NULL, 'scene.start.prologue.acting.t3', 'Дворы разбросаны. До дальних домов не всякая подвода доберётся.', 'Дорожный пролог, 1:47. После выхода из рощи открылись река, озеро, село и широкие поля. Внутренняя мысль аватара «Временная»; показывается субтитром и озвучивается.', 'Природные условия хорошие; одной землёй разруху хозяйства не объяснить.', 'Дать каждому аватару увидеть в одной панораме свой способ взяться за хозяйство.', 'Практичная речь опытной руководительницы; сохранить женский род, не превращать заботу в образ матери села. Не обещать конкретный юнит или решение до осмотра хозяйства.', 'ai/prologue-avatar-thoughts-draft.md#11-временная', 2, 2, 0, 408);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.acting.t5', 'scene.start.prologue', 'scene', 'spoken_thought', 'acting', 'prologue', 'scene', 'scene.start.prologue#t5', 'chairman', NULL, NULL, NULL, 'start.prologue.t5', 'female', 'Выбран avatar.key = acting; адрес пролога 2:42.', NULL, 'scene.start.prologue.acting.t4', 'Один мост. Размоет подъезд — ни врача не привезти, ни больного не вывезти.', 'Дорожный пролог, 2:42. Телега только что съехала с единственного моста через реку. Внутренняя мысль аватара «Временная»; показывается субтитром и озвучивается.', 'Вся связь с районом зависит от одной переправы.', 'Показать, какой риск или человеческое последствие первым замечает аватар.', 'Практичная речь опытной руководительницы; сохранить женский род, не превращать заботу в образ матери села. Сохранить единственность моста и зависимость связи с районом.', 'ai/prologue-avatar-thoughts-draft.md#11-временная', 2, 2, 0, 508);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.acting.t6', 'scene.start.prologue', 'scene', 'spoken_thought', 'acting', 'prologue', 'scene', 'scene.start.prologue#t6', 'chairman', NULL, NULL, NULL, 'start.prologue.t6', 'female', 'Выбран avatar.key = acting; адрес пролога 3:07.', NULL, 'scene.start.prologue.acting.t5', 'Земля брошена не за один сезон. Сначала узнаю, где не хватило рук и тяги.', 'Дорожный пролог, 3:07. У дороги видна залежь, а дальше читаются большие заброшенные поля. Внутренняя мысль аватара «Временная»; показывается субтитром и озвучивается.', 'Пашню не обрабатывали уже несколько сезонов.', 'Перевести обещание панорамы в первое конкретное разочарование.', 'Практичная речь опытной руководительницы; сохранить женский род, не превращать заботу в образ матери села. Не называть точную причину запустения: герой её ещё не знает.', 'ai/prologue-avatar-thoughts-draft.md#11-временная', 2, 2, 0, 608);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.acting.t7', 'scene.start.prologue', 'scene', 'spoken_thought', 'acting', 'prologue', 'scene', 'scene.start.prologue#t7', 'chairman', NULL, NULL, NULL, 'start.prologue.t7', 'female', 'Выбран avatar.key = acting; адрес пролога 3:56.', NULL, 'scene.start.prologue.acting.t6', 'Коровы голодные. Надо сразу проверить корм и поговорить с теми, кто за ними ходит.', 'Дорожный пролог, 3:56. Слева уже слышно голодных коров; жители у дороги молча смотрят вслед телеге. Внутренняя мысль аватара «Временная»; показывается субтитром и озвучивается.', 'Скоту не хватает корма, а жители только наблюдают за новым председателем.', 'Дать первый живой сигнал хозяйственной беды и реакцию аватара на молчаливую встречу.', 'Практичная речь опытной руководительницы; сохранить женский род, не превращать заботу в образ матери села. Не угадывать мысли жителей и не утверждать, что они уже что-либо рассказали.', 'ai/prologue-avatar-thoughts-draft.md#11-временная', 2, 2, 0, 708);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.acting.t8', 'scene.start.prologue', 'scene', 'spoken_thought', 'acting', 'prologue', 'scene', 'scene.start.prologue#t8', 'chairman', NULL, NULL, NULL, 'start.prologue.t8', 'female', 'Выбран avatar.key = acting; адрес пролога 4:44.', NULL, 'scene.start.prologue.acting.t7', 'Я знала, что будет трудно. Но не думала, что встречать меня будут у развалин.', 'Дорожный пролог, 4:44. У полуразвалившейся церкви ждёт толпа; телега ещё не остановилась. Внутренняя мысль аватара «Временная»; показывается субтитром и озвучивается.', 'Вид развалин разочаровывает; председатель ещё не знает, где внутри устроены склад и кабинет.', 'Закончить дорожный портрет аватара его первой реакцией на место будущей ответственности.', 'Практичная речь опытной руководительницы; сохранить женский род, не превращать заботу в образ матери села. Не называть назначение церкви, склада и пристройки до остановки.', 'ai/prologue-avatar-thoughts-draft.md#11-временная', 2, 2, 0, 808);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.dealer.t1', 'scene.start.prologue', 'scene', 'spoken_thought', 'dealer', 'prologue', 'scene', 'scene.start.prologue#t1', 'chairman', NULL, NULL, NULL, 'start.prologue.t1', 'male', 'Выбран avatar.key = dealer; адрес пролога 0:06.', NULL, NULL, 'Позвольте, это уже какая-то чертовщина. Берёза та же, а поворота не было.', 'Дорожный пролог, 0:06. В плотном тумане одна и та же берёза прошла слева второй раз. Внутренняя мысль аватара «Делец»; показывается субтитром и озвучивается.', 'Председатель замечает невозможное повторение дороги, но не понимает переход.', 'Сразу дать голос выбранного аватара и показать странность без объяснения.', 'Интеллигентная старомодная учтивость и умеренные торговые образы; без этнической или фонетической карикатуры. Не называть портал и не объяснять природу тумана.', 'ai/prologue-avatar-thoughts-draft.md#10-делец', 2, 2, 0, 107);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.dealer.t2', 'scene.start.prologue', 'scene', 'spoken_thought', 'dealer', 'prologue', 'scene', 'scene.start.prologue#t2', 'chairman', NULL, NULL, NULL, 'start.prologue.t2', 'male', 'Выбран avatar.key = dealer; адрес пролога 0:29.', NULL, 'scene.start.prologue.dealer.t1', 'Редкая удача: зимой почти не было снега, и дорога нас пропустила. В обычную весну эта поездка стоила бы куда дороже.', 'Дорожный пролог, 0:29. После взгляда назад видна обычная мокрая дорога; на экране уже указан апрель 1931 года. Внутренняя мысль аватара «Делец»; показывается субтитром и озвучивается.', 'Малоснежная зима объясняет необычно лёгкий путь и будущую весеннюю распутицу.', 'Объяснить игроку различие первой и обычной весны как знание героя, а не подсказку механики.', 'Интеллигентная старомодная учтивость и умеренные торговые образы; без этнической или фонетической карикатуры. Сохранить причинную связь: мало снега — мало талой воды — дорога временно держит.', 'ai/prologue-avatar-thoughts-draft.md#10-делец', 2, 2, 0, 207);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.dealer.t3', 'scene.start.prologue', 'scene', 'spoken_thought', 'dealer', 'prologue', 'scene', 'scene.start.prologue#t3', 'chairman', NULL, NULL, NULL, 'start.prologue.t3', 'male', 'Выбран avatar.key = dealer; адрес пролога 0:48.', NULL, 'scene.start.prologue.dealer.t2', 'Кладбище у дороги. Стало быть, село старое; придётся сперва осмотреться.', 'Дорожный пролог, 0:48. Кладбище видно за голыми деревьями слева от дороги. Внутренняя мысль аватара «Делец»; показывается субтитром и озвучивается.', 'Кладбище показывает, что село и его связи старше колхоза.', 'Показать отношение аватара к прошлому незнакомого или родного села.', 'Интеллигентная старомодная учтивость и умеренные торговые образы; без этнической или фонетической карикатуры. Не приписывать незнакомым жителям мысли, память или намерения.', 'ai/prologue-avatar-thoughts-draft.md#10-делец', 2, 2, 0, 307);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.dealer.t4', 'scene.start.prologue', 'scene', 'spoken_thought', 'dealer', 'prologue', 'scene', 'scene.start.prologue#t4', 'chairman', NULL, NULL, NULL, 'start.prologue.t4', 'male', 'Выбран avatar.key = dealer; адрес пролога 1:47.', NULL, 'scene.start.prologue.dealer.t3', 'Вода, лес, земля и дорога в район — набор недурной. Теперь посмотрим, как всем этим здесь распоряжались.', 'Дорожный пролог, 1:47. После выхода из рощи открылись река, озеро, село и широкие поля. Внутренняя мысль аватара «Делец»; показывается субтитром и озвучивается.', 'Природные условия хорошие; одной землёй разруху хозяйства не объяснить.', 'Дать каждому аватару увидеть в одной панораме свой способ взяться за хозяйство.', 'Интеллигентная старомодная учтивость и умеренные торговые образы; без этнической или фонетической карикатуры. Не обещать конкретный юнит или решение до осмотра хозяйства.', 'ai/prologue-avatar-thoughts-draft.md#10-делец', 2, 2, 0, 407);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.dealer.t5', 'scene.start.prologue', 'scene', 'spoken_thought', 'dealer', 'prologue', 'scene', 'scene.start.prologue#t5', 'chairman', NULL, NULL, NULL, 'start.prologue.t5', 'male', 'Выбран avatar.key = dealer; адрес пролога 2:42.', NULL, 'scene.start.prologue.dealer.t4', 'Один мост связывает нас с районом. Его исправность, смею заметить, дорогого стоит.', 'Дорожный пролог, 2:42. Телега только что съехала с единственного моста через реку. Внутренняя мысль аватара «Делец»; показывается субтитром и озвучивается.', 'Вся связь с районом зависит от одной переправы.', 'Показать, какой риск или человеческое последствие первым замечает аватар.', 'Интеллигентная старомодная учтивость и умеренные торговые образы; без этнической или фонетической карикатуры. Сохранить единственность моста и зависимость связи с районом.', 'ai/prologue-avatar-thoughts-draft.md#10-делец', 2, 2, 0, 507);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.dealer.t6', 'scene.start.prologue', 'scene', 'spoken_thought', 'dealer', 'prologue', 'scene', 'scene.start.prologue#t6', 'chairman', NULL, NULL, NULL, 'start.prologue.t6', 'male', 'Выбран avatar.key = dealer; адрес пролога 3:07.', NULL, 'scene.start.prologue.dealer.t5', 'Мне продавали крепкое хозяйство. По этой пашне видно: товар показывали только на словах.', 'Дорожный пролог, 3:07. У дороги видна залежь, а дальше читаются большие заброшенные поля. Внутренняя мысль аватара «Делец»; показывается субтитром и озвучивается.', 'Пашню не обрабатывали уже несколько сезонов.', 'Перевести обещание панорамы в первое конкретное разочарование.', 'Интеллигентная старомодная учтивость и умеренные торговые образы; без этнической или фонетической карикатуры. Не называть точную причину запустения: герой её ещё не знает.', 'ai/prologue-avatar-thoughts-draft.md#10-делец', 2, 2, 0, 607);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.dealer.t7', 'scene.start.prologue', 'scene', 'spoken_thought', 'dealer', 'prologue', 'scene', 'scene.start.prologue#t7', 'chairman', NULL, NULL, NULL, 'start.prologue.t7', 'male', 'Выбран avatar.key = dealer; адрес пролога 3:56.', NULL, 'scene.start.prologue.dealer.t6', 'Скот надо кормить, людям — показать результат. Тогда и договариваться будет легче.', 'Дорожный пролог, 3:56. Слева уже слышно голодных коров; жители у дороги молча смотрят вслед телеге. Внутренняя мысль аватара «Делец»; показывается субтитром и озвучивается.', 'Скоту не хватает корма, а жители только наблюдают за новым председателем.', 'Дать первый живой сигнал хозяйственной беды и реакцию аватара на молчаливую встречу.', 'Интеллигентная старомодная учтивость и умеренные торговые образы; без этнической или фонетической карикатуры. Не угадывать мысли жителей и не утверждать, что они уже что-либо рассказали.', 'ai/prologue-avatar-thoughts-draft.md#10-делец', 2, 2, 0, 707);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.dealer.t8', 'scene.start.prologue', 'scene', 'spoken_thought', 'dealer', 'prologue', 'scene', 'scene.start.prologue#t8', 'chairman', NULL, NULL, NULL, 'start.prologue.t8', 'male', 'Выбран avatar.key = dealer; адрес пролога 4:44.', NULL, 'scene.start.prologue.dealer.t7', 'Вместо обещанного крепкого хозяйства — полуразвалившаяся церковь. Теперь ясно, почему меня торопили с назначением.', 'Дорожный пролог, 4:44. У полуразвалившейся церкви ждёт толпа; телега ещё не остановилась. Внутренняя мысль аватара «Делец»; показывается субтитром и озвучивается.', 'Вид развалин разочаровывает; председатель ещё не знает, где внутри устроены склад и кабинет.', 'Закончить дорожный портрет аватара его первой реакцией на место будущей ответственности.', 'Интеллигентная старомодная учтивость и умеренные торговые образы; без этнической или фонетической карикатуры. Не называть назначение церкви, склада и пристройки до остановки.', 'ai/prologue-avatar-thoughts-draft.md#10-делец', 2, 2, 0, 807);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.ex_chairman.t1', 'scene.start.prologue', 'scene', 'spoken_thought', 'ex_chairman', 'prologue', 'scene', 'scene.start.prologue#t1', 'chairman', NULL, NULL, NULL, 'start.prologue.t1', 'male', 'Выбран avatar.key = ex_chairman; адрес пролога 0:06.', NULL, NULL, 'Чертовщина какая-то. Поворота не было, а берёза та же.', 'Дорожный пролог, 0:06. В плотном тумане одна и та же берёза прошла слева второй раз. Внутренняя мысль аватара «Снятый председатель»; показывается субтитром и озвучивается.', 'Председатель замечает невозможное повторение дороги, но не понимает переход.', 'Сразу дать голос выбранного аватара и показать странность без объяснения.', 'Опытная настороженность без вечного цинизма; он знает управление, но не мысли незнакомых жителей. Не называть портал и не объяснять природу тумана.', 'ai/prologue-avatar-thoughts-draft.md#7-снятый-председатель', 2, 2, 0, 104);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.ex_chairman.t2', 'scene.start.prologue', 'scene', 'spoken_thought', 'ex_chairman', 'prologue', 'scene', 'scene.start.prologue#t2', 'chairman', NULL, NULL, NULL, 'start.prologue.t2', 'male', 'Выбран avatar.key = ex_chairman; адрес пролога 0:29.', NULL, 'scene.start.prologue.ex_chairman.t1', 'Малоснежная зима спасла дорогу. В обычную весну отсюда до района не пробиться — и на быструю помощь рассчитывать нечего.', 'Дорожный пролог, 0:29. После взгляда назад видна обычная мокрая дорога; на экране уже указан апрель 1931 года. Внутренняя мысль аватара «Снятый председатель»; показывается субтитром и озвучивается.', 'Малоснежная зима объясняет необычно лёгкий путь и будущую весеннюю распутицу.', 'Объяснить игроку различие первой и обычной весны как знание героя, а не подсказку механики.', 'Опытная настороженность без вечного цинизма; он знает управление, но не мысли незнакомых жителей. Сохранить причинную связь: мало снега — мало талой воды — дорога временно держит.', 'ai/prologue-avatar-thoughts-draft.md#7-снятый-председатель', 2, 2, 0, 204);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.ex_chairman.t3', 'scene.start.prologue', 'scene', 'spoken_thought', 'ex_chairman', 'prologue', 'scene', 'scene.start.prologue#t3', 'chairman', NULL, NULL, NULL, 'start.prologue.t3', 'male', 'Выбран avatar.key = ex_chairman; адрес пролога 0:48.', NULL, 'scene.start.prologue.ex_chairman.t2', 'Село старое. В районной справке не написано, кто здесь с кем родня и кто на кого в обиде.', 'Дорожный пролог, 0:48. Кладбище видно за голыми деревьями слева от дороги. Внутренняя мысль аватара «Снятый председатель»; показывается субтитром и озвучивается.', 'Кладбище показывает, что село и его связи старше колхоза.', 'Показать отношение аватара к прошлому незнакомого или родного села.', 'Опытная настороженность без вечного цинизма; он знает управление, но не мысли незнакомых жителей. Не приписывать незнакомым жителям мысли, память или намерения.', 'ai/prologue-avatar-thoughts-draft.md#7-снятый-председатель', 2, 2, 0, 304);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.ex_chairman.t4', 'scene.start.prologue', 'scene', 'spoken_thought', 'ex_chairman', 'prologue', 'scene', 'scene.start.prologue#t4', 'chairman', NULL, NULL, NULL, 'start.prologue.t4', 'male', 'Выбран avatar.key = ex_chairman; адрес пролога 1:47.', NULL, 'scene.start.prologue.ex_chairman.t3', 'Условия хорошие. Значит, разруху одной землёй не объяснишь.', 'Дорожный пролог, 1:47. После выхода из рощи открылись река, озеро, село и широкие поля. Внутренняя мысль аватара «Снятый председатель»; показывается субтитром и озвучивается.', 'Природные условия хорошие; одной землёй разруху хозяйства не объяснить.', 'Дать каждому аватару увидеть в одной панораме свой способ взяться за хозяйство.', 'Опытная настороженность без вечного цинизма; он знает управление, но не мысли незнакомых жителей. Не обещать конкретный юнит или решение до осмотра хозяйства.', 'ai/prologue-avatar-thoughts-draft.md#7-снятый-председатель', 2, 2, 0, 404);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.ex_chairman.t5', 'scene.start.prologue', 'scene', 'spoken_thought', 'ex_chairman', 'prologue', 'scene', 'scene.start.prologue#t5', 'chairman', NULL, NULL, NULL, 'start.prologue.t5', 'male', 'Выбран avatar.key = ex_chairman; адрес пролога 2:42.', NULL, 'scene.start.prologue.ex_chairman.t4', 'Один мост на всю связь с районом. Вот и первый риск.', 'Дорожный пролог, 2:42. Телега только что съехала с единственного моста через реку. Внутренняя мысль аватара «Снятый председатель»; показывается субтитром и озвучивается.', 'Вся связь с районом зависит от одной переправы.', 'Показать, какой риск или человеческое последствие первым замечает аватар.', 'Опытная настороженность без вечного цинизма; он знает управление, но не мысли незнакомых жителей. Сохранить единственность моста и зависимость связи с районом.', 'ai/prologue-avatar-thoughts-draft.md#7-снятый-председатель', 2, 2, 0, 504);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.ex_chairman.t6', 'scene.start.prologue', 'scene', 'spoken_thought', 'ex_chairman', 'prologue', 'scene', 'scene.start.prologue#t6', 'chairman', NULL, NULL, NULL, 'start.prologue.t6', 'male', 'Выбран avatar.key = ex_chairman; адрес пролога 3:07.', NULL, 'scene.start.prologue.ex_chairman.t5', 'Залежь тянется вдоль дороги. Это не один сорванный сев: поле запускали несколько лет.', 'Дорожный пролог, 3:07. У дороги видна залежь, а дальше читаются большие заброшенные поля. Внутренняя мысль аватара «Снятый председатель»; показывается субтитром и озвучивается.', 'Пашню не обрабатывали уже несколько сезонов.', 'Перевести обещание панорамы в первое конкретное разочарование.', 'Опытная настороженность без вечного цинизма; он знает управление, но не мысли незнакомых жителей. Не называть точную причину запустения: герой её ещё не знает.', 'ai/prologue-avatar-thoughts-draft.md#7-снятый-председатель', 2, 2, 0, 604);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.ex_chairman.t7', 'scene.start.prologue', 'scene', 'spoken_thought', 'ex_chairman', 'prologue', 'scene', 'scene.start.prologue#t7', 'chairman', NULL, NULL, NULL, 'start.prologue.t7', 'male', 'Выбран avatar.key = ex_chairman; адрес пролога 3:56.', NULL, 'scene.start.prologue.ex_chairman.t6', 'Голодный скот слышно сразу. А люди молчат и только смотрят, кого им прислали.', 'Дорожный пролог, 3:56. Слева уже слышно голодных коров; жители у дороги молча смотрят вслед телеге. Внутренняя мысль аватара «Снятый председатель»; показывается субтитром и озвучивается.', 'Скоту не хватает корма, а жители только наблюдают за новым председателем.', 'Дать первый живой сигнал хозяйственной беды и реакцию аватара на молчаливую встречу.', 'Опытная настороженность без вечного цинизма; он знает управление, но не мысли незнакомых жителей. Не угадывать мысли жителей и не утверждать, что они уже что-либо рассказали.', 'ai/prologue-avatar-thoughts-draft.md#7-снятый-председатель', 2, 2, 0, 704);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.ex_chairman.t8', 'scene.start.prologue', 'scene', 'spoken_thought', 'ex_chairman', 'prologue', 'scene', 'scene.start.prologue#t8', 'chairman', NULL, NULL, NULL, 'start.prologue.t8', 'male', 'Выбран avatar.key = ex_chairman; адрес пролога 4:44.', NULL, 'scene.start.prologue.ex_chairman.t7', 'Всё же я надеялся увидеть здесь хоть что-нибудь целое. Второй шанс опять начинается с развалин.', 'Дорожный пролог, 4:44. У полуразвалившейся церкви ждёт толпа; телега ещё не остановилась. Внутренняя мысль аватара «Снятый председатель»; показывается субтитром и озвучивается.', 'Вид развалин разочаровывает; председатель ещё не знает, где внутри устроены склад и кабинет.', 'Закончить дорожный портрет аватара его первой реакцией на место будущей ответственности.', 'Опытная настороженность без вечного цинизма; он знает управление, но не мысли незнакомых жителей. Не называть назначение церкви, склада и пристройки до остановки.', 'ai/prologue-avatar-thoughts-draft.md#7-снятый-председатель', 2, 2, 0, 804);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.old_fighter.t1', 'scene.start.prologue', 'scene', 'spoken_thought', 'old_fighter', 'prologue', 'scene', 'scene.start.prologue#t1', 'chairman', NULL, NULL, NULL, 'start.prologue.t1', 'male', 'Выбран avatar.key = old_fighter; адрес пролога 0:06.', NULL, NULL, 'Вот чертовщина. Шли прямо, а берёза второй раз попалась.', 'Дорожный пролог, 0:06. В плотном тумане одна и та же берёза прошла слева второй раз. Внутренняя мысль аватара «Старый боец»; показывается субтитром и озвучивается.', 'Председатель замечает невозможное повторение дороги, но не понимает переход.', 'Сразу дать голос выбранного аватара и показать странность без объяснения.', 'Короткая речь лихого кавалерийского командира; без названия войны, насилия и карикатурной рубки фраз. Не называть портал и не объяснять природу тумана.', 'ai/prologue-avatar-thoughts-draft.md#9-старый-боец', 2, 2, 0, 106);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.old_fighter.t2', 'scene.start.prologue', 'scene', 'spoken_thought', 'old_fighter', 'prologue', 'scene', 'scene.start.prologue#t2', 'chairman', NULL, NULL, NULL, 'start.prologue.t2', 'male', 'Выбран avatar.key = old_fighter; адрес пролога 0:29.', NULL, 'scene.start.prologue.old_fighter.t1', 'Снега зимой было мало — потому и прошли легко. В обычную весну любой обоз здесь сядет по ступицу.', 'Дорожный пролог, 0:29. После взгляда назад видна обычная мокрая дорога; на экране уже указан апрель 1931 года. Внутренняя мысль аватара «Старый боец»; показывается субтитром и озвучивается.', 'Малоснежная зима объясняет необычно лёгкий путь и будущую весеннюю распутицу.', 'Объяснить игроку различие первой и обычной весны как знание героя, а не подсказку механики.', 'Короткая речь лихого кавалерийского командира; без названия войны, насилия и карикатурной рубки фраз. Сохранить причинную связь: мало снега — мало талой воды — дорога временно держит.', 'ai/prologue-avatar-thoughts-draft.md#9-старый-боец', 2, 2, 0, 206);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.old_fighter.t3', 'scene.start.prologue', 'scene', 'spoken_thought', 'old_fighter', 'prologue', 'scene', 'scene.start.prologue#t3', 'chairman', NULL, NULL, NULL, 'start.prologue.t3', 'male', 'Выбран avatar.key = old_fighter; адрес пролога 0:48.', NULL, 'scene.start.prologue.old_fighter.t2', 'Кладбище близко. Значит, и село уже за рощей.', 'Дорожный пролог, 0:48. Кладбище видно за голыми деревьями слева от дороги. Внутренняя мысль аватара «Старый боец»; показывается субтитром и озвучивается.', 'Кладбище показывает, что село и его связи старше колхоза.', 'Показать отношение аватара к прошлому незнакомого или родного села.', 'Короткая речь лихого кавалерийского командира; без названия войны, насилия и карикатурной рубки фраз. Не приписывать незнакомым жителям мысли, память или намерения.', 'ai/prologue-avatar-thoughts-draft.md#9-старый-боец', 2, 2, 0, 306);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.old_fighter.t4', 'scene.start.prologue', 'scene', 'spoken_thought', 'old_fighter', 'prologue', 'scene', 'scene.start.prologue#t4', 'chairman', NULL, NULL, NULL, 'start.prologue.t4', 'male', 'Выбран avatar.key = old_fighter; адрес пролога 1:47.', NULL, 'scene.start.prologue.old_fighter.t3', 'Вся долина как на ладони: село, вода, поля. Работать можно.', 'Дорожный пролог, 1:47. После выхода из рощи открылись река, озеро, село и широкие поля. Внутренняя мысль аватара «Старый боец»; показывается субтитром и озвучивается.', 'Природные условия хорошие; одной землёй разруху хозяйства не объяснить.', 'Дать каждому аватару увидеть в одной панораме свой способ взяться за хозяйство.', 'Короткая речь лихого кавалерийского командира; без названия войны, насилия и карикатурной рубки фраз. Не обещать конкретный юнит или решение до осмотра хозяйства.', 'ai/prologue-avatar-thoughts-draft.md#9-старый-боец', 2, 2, 0, 406);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.old_fighter.t5', 'scene.start.prologue', 'scene', 'spoken_thought', 'old_fighter', 'prologue', 'scene', 'scene.start.prologue#t5', 'chairman', NULL, NULL, NULL, 'start.prologue.t5', 'male', 'Выбран avatar.key = old_fighter; адрес пролога 2:42.', NULL, 'scene.start.prologue.old_fighter.t4', 'Мост — единственный проход. Держать исправным.', 'Дорожный пролог, 2:42. Телега только что съехала с единственного моста через реку. Внутренняя мысль аватара «Старый боец»; показывается субтитром и озвучивается.', 'Вся связь с районом зависит от одной переправы.', 'Показать, какой риск или человеческое последствие первым замечает аватар.', 'Короткая речь лихого кавалерийского командира; без названия войны, насилия и карикатурной рубки фраз. Сохранить единственность моста и зависимость связи с районом.', 'ai/prologue-avatar-thoughts-draft.md#9-старый-боец', 2, 2, 0, 506);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.old_fighter.t6', 'scene.start.prologue', 'scene', 'spoken_thought', 'old_fighter', 'prologue', 'scene', 'scene.start.prologue#t6', 'chairman', NULL, NULL, NULL, 'start.prologue.t6', 'male', 'Выбран avatar.key = old_fighter; адрес пролога 3:07.', NULL, 'scene.start.prologue.old_fighter.t5', 'Поле брошено. Такой рубеж наскоком не взять: нужны люди и тяга.', 'Дорожный пролог, 3:07. У дороги видна залежь, а дальше читаются большие заброшенные поля. Внутренняя мысль аватара «Старый боец»; показывается субтитром и озвучивается.', 'Пашню не обрабатывали уже несколько сезонов.', 'Перевести обещание панорамы в первое конкретное разочарование.', 'Короткая речь лихого кавалерийского командира; без названия войны, насилия и карикатурной рубки фраз. Не называть точную причину запустения: герой её ещё не знает.', 'ai/prologue-avatar-thoughts-draft.md#9-старый-боец', 2, 2, 0, 606);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.old_fighter.t7', 'scene.start.prologue', 'scene', 'spoken_thought', 'old_fighter', 'prologue', 'scene', 'scene.start.prologue#t7', 'chairman', NULL, NULL, NULL, 'start.prologue.t7', 'male', 'Выбран avatar.key = old_fighter; адрес пролога 3:56.', NULL, 'scene.start.prologue.old_fighter.t6', 'Скот накормить. Людей собрать. Дальше пойдём по порядку.', 'Дорожный пролог, 3:56. Слева уже слышно голодных коров; жители у дороги молча смотрят вслед телеге. Внутренняя мысль аватара «Старый боец»; показывается субтитром и озвучивается.', 'Скоту не хватает корма, а жители только наблюдают за новым председателем.', 'Дать первый живой сигнал хозяйственной беды и реакцию аватара на молчаливую встречу.', 'Короткая речь лихого кавалерийского командира; без названия войны, насилия и карикатурной рубки фраз. Не угадывать мысли жителей и не утверждать, что они уже что-либо рассказали.', 'ai/prologue-avatar-thoughts-draft.md#9-старый-боец', 2, 2, 0, 706);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.old_fighter.t8', 'scene.start.prologue', 'scene', 'spoken_thought', 'old_fighter', 'prologue', 'scene', 'scene.start.prologue#t8', 'chairman', NULL, NULL, NULL, 'start.prologue.t8', 'male', 'Выбран avatar.key = old_fighter; адрес пролога 4:44.', NULL, 'scene.start.prologue.old_fighter.t7', 'Церковь едва стоит. Не таким я представлял новый колхоз. Где расположиться — выясним.', 'Дорожный пролог, 4:44. У полуразвалившейся церкви ждёт толпа; телега ещё не остановилась. Внутренняя мысль аватара «Старый боец»; показывается субтитром и озвучивается.', 'Вид развалин разочаровывает; председатель ещё не знает, где внутри устроены склад и кабинет.', 'Закончить дорожный портрет аватара его первой реакцией на место будущей ответственности.', 'Короткая речь лихого кавалерийского командира; без названия войны, насилия и карикатурной рубки фраз. Не называть назначение церкви, склада и пристройки до остановки.', 'ai/prologue-avatar-thoughts-draft.md#9-старый-боец', 2, 2, 0, 806);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.promoted.t1', 'scene.start.prologue', 'scene', 'spoken_thought', 'promoted', 'prologue', 'scene', 'scene.start.prologue#t1', 'chairman', NULL, NULL, NULL, 'start.prologue.t1', 'male', 'Выбран avatar.key = promoted; адрес пролога 0:06.', NULL, NULL, 'Какая-то чертовщина. Маршрут верный, поворотов не было.', 'Дорожный пролог, 0:06. В плотном тумане одна и та же берёза прошла слева второй раз. Внутренняя мысль аватара «Партийный выдвиженец»; показывается субтитром и озвучивается.', 'Председатель замечает невозможное повторение дороги, но не понимает переход.', 'Сразу дать голос выбранного аватара и показать странность без объяснения.', 'Уверенная речь человека со связями и привычкой к согласованиям; канцелярит не должен становиться пародией. Не называть портал и не объяснять природу тумана.', 'ai/prologue-avatar-thoughts-draft.md#8-партийный-выдвиженец', 2, 2, 0, 105);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.promoted.t2', 'scene.start.prologue', 'scene', 'spoken_thought', 'promoted', 'prologue', 'scene', 'scene.start.prologue#t2', 'chairman', NULL, NULL, NULL, 'start.prologue.t2', 'male', 'Выбран avatar.key = promoted; адрес пролога 0:29.', NULL, 'scene.start.prologue.promoted.t1', 'Доехали без задержки только из-за малоснежной зимы. В обычную весну связь с районом будет отдельным вопросом.', 'Дорожный пролог, 0:29. После взгляда назад видна обычная мокрая дорога; на экране уже указан апрель 1931 года. Внутренняя мысль аватара «Партийный выдвиженец»; показывается субтитром и озвучивается.', 'Малоснежная зима объясняет необычно лёгкий путь и будущую весеннюю распутицу.', 'Объяснить игроку различие первой и обычной весны как знание героя, а не подсказку механики.', 'Уверенная речь человека со связями и привычкой к согласованиям; канцелярит не должен становиться пародией. Сохранить причинную связь: мало снега — мало талой воды — дорога временно держит.', 'ai/prologue-avatar-thoughts-draft.md#8-партийный-выдвиженец', 2, 2, 0, 205);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.promoted.t3', 'scene.start.prologue', 'scene', 'spoken_thought', 'promoted', 'prologue', 'scene', 'scene.start.prologue#t3', 'chairman', NULL, NULL, NULL, 'start.prologue.t3', 'male', 'Выбран avatar.key = promoted; адрес пролога 0:48.', NULL, 'scene.start.prologue.promoted.t2', 'Кладбище у дороги. Значит, село старое; местные порядки придётся учитывать.', 'Дорожный пролог, 0:48. Кладбище видно за голыми деревьями слева от дороги. Внутренняя мысль аватара «Партийный выдвиженец»; показывается субтитром и озвучивается.', 'Кладбище показывает, что село и его связи старше колхоза.', 'Показать отношение аватара к прошлому незнакомого или родного села.', 'Уверенная речь человека со связями и привычкой к согласованиям; канцелярит не должен становиться пародией. Не приписывать незнакомым жителям мысли, память или намерения.', 'ai/prologue-avatar-thoughts-draft.md#8-партийный-выдвиженец', 2, 2, 0, 305);
