INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t6', 'scene.start.prologue', 'scene', 'spoken_thought', 'worker', 'prologue', 'scene', 'scene.start.prologue#t6', 'chairman', NULL, NULL, NULL, 'start.prologue.t6', 'male', 'Выбран avatar.key = worker; адрес пролога 3:07.', NULL, 'scene.start.prologue.worker.t5', 'Поле большое, а работы на нём нет. Здесь не один участок встал — всё хозяйство стоит.', 'Дорожный пролог, 3:07. У дороги видна залежь, а дальше читаются большие заброшенные поля. Внутренняя мысль аватара «Рабочий»; показывается субтитром и озвучивается.', 'Пашню не обрабатывали уже несколько сезонов.', 'Перевести обещание панорамы в первое конкретное разочарование.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Не называть точную причину запустения: герой её ещё не знает.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 2, 2, 0, 602);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t7', 'scene.start.prologue', 'scene', 'spoken_thought', 'worker', 'prologue', 'scene', 'scene.start.prologue#t7', 'chairman', NULL, NULL, NULL, 'start.prologue.t7', 'male', 'Выбран avatar.key = worker; адрес пролога 3:56.', NULL, 'scene.start.prologue.worker.t6', 'Сначала корм для скота. Потом разберусь, где работа встала.', 'Дорожный пролог, 3:56. Слева уже слышно голодных коров; жители у дороги молча смотрят вслед телеге. Внутренняя мысль аватара «Рабочий»; показывается субтитром и озвучивается.', 'Скоту не хватает корма, а жители только наблюдают за новым председателем.', 'Дать первый живой сигнал хозяйственной беды и реакцию аватара на молчаливую встречу.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Не угадывать мысли жителей и не утверждать, что они уже что-либо рассказали.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 2, 2, 0, 702);
INSERT INTO "line" ("key", "scene_key", "namespace", "kind", "thought_avatar", "thought_place", "thought_trigger_kind", "thought_trigger_ref", "speaker_slot", "addressee_slot", "relationship", "choice_group_key", "variant_key", "grammatical_gender", "condition_ref", "result", "previous_key", "text", "context", "meaning", "intent", "keep", "source_ref", "rev", "approved_rev", "deprecated", "sort") VALUES ('scene.start.prologue.worker.t8', 'scene.start.prologue', 'scene', 'spoken_thought', 'worker', 'prologue', 'scene', 'scene.start.prologue#t8', 'chairman', NULL, NULL, NULL, 'start.prologue.t8', 'male', 'Выбран avatar.key = worker; адрес пролога 4:44.', NULL, 'scene.start.prologue.worker.t7', 'Церковь еле стоит. Начинать придётся с развалин.', 'Дорожный пролог, 4:44. У полуразвалившейся церкви ждёт толпа; телега ещё не остановилась. Внутренняя мысль аватара «Рабочий»; показывается субтитром и озвучивается.', 'Вид развалин разочаровывает; председатель ещё не знает, где внутри устроены склад и кабинет.', 'Закончить дорожный портрет аватара его первой реакцией на место будущей ответственности.', 'Заводская деловитость и производственные слова; не превращать каждую мысль в сравнение с заводом. Не называть назначение церкви, склада и пристройки до остановки.', 'ai/prologue-avatar-thoughts-draft.md#5-рабочий', 2, 2, 0, 802);
